function parseDueDate(text) {
    if (!text) return null;
    const t = text.toLowerCase().trim();
    const days = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
    const now = new Date();

    const timeMatch = t.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)/);
    let hours = null, minutes = 0;
    if (timeMatch) {
        hours = parseInt(timeMatch[1], 10);
        minutes = timeMatch[2] ? parseInt(timeMatch[2], 10) : 0;
        const meridiem = timeMatch[3];
        if (meridiem === 'pm' && hours !== 12) hours += 12;
        if (meridiem === 'am' && hours === 12) hours = 0;
    }

    function applyTimeOrEndOfDay(d) {
        if (hours !== null) {
            d.setHours(hours, minutes, 0, 0);
        } else {
            d.setHours(23, 59, 0, 0);
        }
        return d.getTime();
    }

    if (t.includes('today')) {
        const d = new Date(now);
        return applyTimeOrEndOfDay(d);
    }
    if (t.includes('tomorrow')) {
        const d = new Date(now);
        d.setDate(d.getDate() + 1);
        return applyTimeOrEndOfDay(d);
    }

    const cleaned = t.replace(/^next\s+/, '').replace(/^this\s+/, '');
    const dayIndex = days.findIndex(day => cleaned.includes(day));
    if (dayIndex !== -1) {
        const d = new Date(now);
        let diff = (dayIndex - d.getDay() + 7) % 7;
        if (diff === 0) diff = 7;
        d.setDate(d.getDate() + diff);
        return applyTimeOrEndOfDay(d);
    }

    if (hours !== null) {
        const d = new Date(now);
        return applyTimeOrEndOfDay(d);
    }

    const parsedTime = Date.parse(text);
    if (!isNaN(parsedTime)) return parsedTime;
    return null;
}

